using System;
using System.Collections.Generic;
using System.Data;
using System.Web;
using InformationWeb;
using InformationWebObject;

namespace InformationWeb.Controls.Information.About
{
    public static class AboutPageContentHelper
    {
        private const string ContextKey = "AboutPageContent_AboutUs";

        public static string C(string strContentCode)
        {
            return GetValue(strContentCode, "Content");
        }

        public static string Img(string strContentCode)
        {
            return GetValue(strContentCode, "ImageUrl");
        }

        public static string Link(string strContentCode)
        {
            return GetValue(strContentCode, "LinkUrl");
        }

        public static string Num(string strContentCode)
        {
            string strValue = GetValue(strContentCode, "NumberValue");
            decimal decValue = 0;

            if (decimal.TryParse(strValue, out decValue))
            {
                if (decValue == decimal.Truncate(decValue))
                    return decValue.ToString("0");

                return decValue.ToString("0.##");
            }

            return strValue;
        }

        public static string Suffix(string strContentCode)
        {
            return GetValue(strContentCode, "NumberSuffix");
        }

        private static string GetValue(string strContentCode, string strColumnName)
        {
            Dictionary<string, DataRow> dicContent = GetContentDictionary();
            if (dicContent == null || string.IsNullOrEmpty(strContentCode) || string.IsNullOrEmpty(strColumnName))
                return string.Empty;

            if (!dicContent.ContainsKey(strContentCode))
                return string.Empty;

            DataRow drwData = dicContent[strContentCode];
            if (drwData == null || drwData.Table.Columns.IndexOf(strColumnName) < 0)
                return string.Empty;

            object objValue = drwData[strColumnName];
            if (objValue == null || objValue == DBNull.Value)
                return string.Empty;

            return objValue.ToString();
        }

        private static Dictionary<string, DataRow> GetContentDictionary()
        {
            HttpContext objContext = HttpContext.Current;
            if (objContext == null)
                return new Dictionary<string, DataRow>(StringComparer.OrdinalIgnoreCase);

            if (objContext.Items[ContextKey] != null)
                return (Dictionary<string, DataRow>)objContext.Items[ContextKey];

            Dictionary<string, DataRow> dicContent = LoadContentDictionary();
            objContext.Items[ContextKey] = dicContent;
            return dicContent;
        }

        private static Dictionary<string, DataRow> LoadContentDictionary()
        {
            Dictionary<string, DataRow> dicContent = new Dictionary<string, DataRow>(StringComparer.OrdinalIgnoreCase);

            try
            {
                INFO_Information objInformation = new INFO_Information();
                DataTable dtbData = objInformation.GetDataTable(
                    "INFO_AboutPageContent_List",
                    "@PageCode", "AboutUs",
                    "@LanguageID", ResManager.CurrentLanguageID
                );

                if (dtbData == null)
                    return dicContent;

                foreach (DataRow drwData in dtbData.Rows)
                {
                    if (drwData.Table.Columns.IndexOf("ContentCode") < 0) continue;
                    if (drwData["ContentCode"] == null || drwData["ContentCode"] == DBNull.Value) continue;

                    string strContentCode = drwData["ContentCode"].ToString();
                    if (!dicContent.ContainsKey(strContentCode))
                        dicContent.Add(strContentCode, drwData);
                }
            }
            catch
            {
                dicContent.Clear();
            }

            return dicContent;
        }
    }
}

