using System.Collections.Generic;
using System.Data;
using System.Web.UI;
using InformationWeb;
using InformationWebObject;

namespace InformationWeb.Controls.Information.About
{
    public partial class SectionAboutUs : System.Web.UI.UserControl
    {
        private Dictionary<string, DataRow> dicContent;

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!Page.IsPostBack)
                LoadData();
        }

        private void LoadData()
        {
            dicContent = new Dictionary<string, DataRow>(StringComparer.OrdinalIgnoreCase);

            try
            {
                INFO_Information objInformation = new INFO_Information();
                DataTable dtbData = objInformation.GetDataTable(
                    "INFO_AboutPageContent_List",
                    "@PageCode", "AboutUs",
                    "@LanguageID", ResManager.CurrentLanguageID
                );

                if (dtbData == null) return;

                foreach (DataRow drwData in dtbData.Rows)
                {
                    if (drwData.Table.Columns.IndexOf("ContentCode") < 0) continue;
                    if (drwData["ContentCode"] == null || drwData["ContentCode"] == DBNull.Value) continue;

                    string strContentCode = drwData["ContentCode"].ToString();
                    if (!dicContent.ContainsKey(strContentCode))
                        dicContent.Add(strContentCode, drwData);
                }
            }
            catch
            {
                dicContent.Clear();
            }
        }

        protected string C(string strContentCode)
        {
            return GetValue(strContentCode, "Content");
        }

        protected string Img(string strContentCode)
        {
            return GetValue(strContentCode, "ImageUrl");
        }

        protected string Link(string strContentCode)
        {
            return GetValue(strContentCode, "LinkUrl");
        }

        protected string Num(string strContentCode)
        {
            string strValue = GetValue(strContentCode, "NumberValue");
            decimal decValue = 0;

            if (decimal.TryParse(strValue, out decValue))
            {
                if (decValue == decimal.Truncate(decValue))
                    return decValue.ToString("0");

                return decValue.ToString("0.##");
            }

            return strValue;
        }

        protected string Suffix(string strContentCode)
        {
            return GetValue(strContentCode, "NumberSuffix");
        }

        private string GetValue(string strContentCode, string strColumnName)
        {
            if (dicContent == null || string.IsNullOrEmpty(strContentCode) || string.IsNullOrEmpty(strColumnName))
                return string.Empty;

            if (!dicContent.ContainsKey(strContentCode))
                return string.Empty;

            DataRow drwData = dicContent[strContentCode];
            if (drwData == null || drwData.Table.Columns.IndexOf(strColumnName) < 0)
                return string.Empty;

            object objValue = drwData[strColumnName];
            if (objValue == null || objValue == DBNull.Value)
                return string.Empty;

            return objValue.ToString();
        }
    }
}

