(function () {
  var section = document.querySelector('.ceo-section');
  var col = section && section.querySelector('.ceo-portrait-col');
  var portrait = document.getElementById('ceoPortrait');
  if (!section || !col || !portrait) return;

  var TOP_OFFSET = 100;
  var mql = window.matchMedia('(max-width: 960px)');
  var ticking = false;
  var startScrollY = 0;
  var maxTranslate = 0;

  function measure() {
    portrait.style.transform = '';
    portrait.classList.remove('is-scroll-follow');
    var scrollY = window.pageYOffset || document.documentElement.scrollTop;
    var colRect = col.getBoundingClientRect();
    startScrollY = colRect.top + scrollY;
    maxTranslate = Math.max(0, col.offsetHeight - portrait.offsetHeight);
  }

  function update() {
    ticking = false;

    if (mql.matches) {
      portrait.style.transform = '';
      portrait.classList.remove('is-scroll-follow');
      return;
    }

    var scrollY = window.pageYOffset || document.documentElement.scrollTop;
    var y = scrollY + TOP_OFFSET - startScrollY;

    if (y < 0) y = 0;
    if (y > maxTranslate) y = maxTranslate;

    if (y > 0) {
      portrait.classList.add('is-scroll-follow');
      portrait.style.transform = 'translate3d(0,' + y + 'px,0)';
    } else {
      portrait.classList.remove('is-scroll-follow');
      portrait.style.transform = '';
    }
  }

  function onScroll() {
    if (ticking) return;
    ticking = true;
    if (window.requestAnimationFrame) {
      window.requestAnimationFrame(update);
    } else {
      update();
    }
  }

  function remeasure() {
    measure();
    update();
  }

  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', remeasure);
  window.addEventListener('load', remeasure);

  if (mql.addEventListener) {
    mql.addEventListener('change', remeasure);
  } else if (mql.addListener) {
    mql.addListener(remeasure);
  }

  remeasure();
})();
</script>

