(function () {
  var section = document.querySelector('.ceo-section');
  if (!section) return;

  var col = section.querySelector('.ceo-portrait-col');
  var portrait = section.querySelector('.ceo-portrait');
  if (!col || !portrait) return;

  var mqDesktop = window.matchMedia('(min-width: 961px)');
  var mqReduce = window.matchMedia('(prefers-reduced-motion: reduce)');
  var STICKY_TOP = 100;
  var loopActive = false;

  function reset() {
    portrait.classList.remove('is-follow-scroll');
    portrait.style.transform = '';
  }

  function update() {
    if (!mqDesktop.matches || mqReduce.matches) {
      reset();
      loopActive = false;
      return;
    }

    var colRect = col.getBoundingClientRect();
    var portraitH = portrait.offsetHeight;
    var maxShift = Math.max(0, col.offsetHeight - portraitH);
    var shift = STICKY_TOP - colRect.top;

    if (shift < 0) shift = 0;
    if (shift > maxShift) shift = maxShift;

    if (shift > 0) {
      portrait.classList.add('is-follow-scroll');
      portrait.style.transform = 'translate3d(0,' + shift + 'px,0)';
    } else {
      reset();
    }

    if (loopActive) requestAnimationFrame(update);
  }

  function startLoop() {
    if (loopActive) return;
    loopActive = true;
    requestAnimationFrame(update);
  }

  function onViewportChange() {
    if (mqDesktop.matches && !mqReduce.matches) startLoop();
    else {
      loopActive = false;
      reset();
    }
  }

  window.addEventListener('resize', onViewportChange);
  if (mqDesktop.addListener) mqDesktop.addListener(onViewportChange);
  else if (mqDesktop.addEventListener) mqDesktop.addEventListener('change', onViewportChange);
  window.addEventListener('load', onViewportChange);
  if (document.fonts && document.fonts.ready) {
    document.fonts.ready.then(onViewportChange);
  }
  onViewportChange();
})();

