    /// <summary>
    /// Truy cập INFO_AboutPageContent qua stored procedure (CMS).
    /// </summary>
    public static class AboutPageContentService
    {
        public static DataTable Search(string strPageCode, string strSectionCode, string strKeyword, int? intIsPublished)
        {
            INFO_Information objInformation = new INFO_Information();
            return objInformation.GetDataTable(
                "INFO_AboutPageContent_SearchCMS",
                "@PageCode", string.IsNullOrEmpty(strPageCode) ? (object)DBNull.Value : strPageCode,
                "@SectionCode", string.IsNullOrEmpty(strSectionCode) ? (object)DBNull.Value : strSectionCode,
                "@Keyword", string.IsNullOrEmpty(strKeyword) ? (object)DBNull.Value : strKeyword.Trim(),
                "@IsPublished", intIsPublished.HasValue ? (object)intIsPublished.Value : DBNull.Value
            );
        }

        public static DataTable GetById(long lngAboutPageContentID)
        {
            INFO_Information objInformation = new INFO_Information();
            return objInformation.GetDataTable(
                "INFO_AboutPageContent_GetByID",
                "@AboutPageContentID", lngAboutPageContentID
            );
        }

        public static long Save(
            long lngAboutPageContentID,
            string strPageCode,
            string strSectionCode,
            string strContentCode,
            string strContentType,
            string strTitleVi,
            string strTitleEn,
            string strContentVi,
            string strContentEn,
            string strImageUrl,
            string strLinkUrl,
            decimal? decNumberValue,
            string strNumberSuffix,
            int intSortOrder,
            bool bolIsPublished,
            string strUserName)
        {
            INFO_Information objInformation = new INFO_Information();
            DataTable dtbData = objInformation.GetDataTable(
                "INFO_AboutPageContent_Save",
                "@AboutPageContentID", lngAboutPageContentID > 0 ? (object)lngAboutPageContentID : DBNull.Value,
                "@PageCode", strPageCode,
                "@SectionCode", strSectionCode,
                "@ContentCode", strContentCode,
                "@ContentType", strContentType,
                "@TitleVi", string.IsNullOrEmpty(strTitleVi) ? (object)DBNull.Value : strTitleVi,
                "@TitleEn", string.IsNullOrEmpty(strTitleEn) ? (object)DBNull.Value : strTitleEn,
                "@ContentVi", string.IsNullOrEmpty(strContentVi) ? (object)DBNull.Value : strContentVi,
                "@ContentEn", string.IsNullOrEmpty(strContentEn) ? (object)DBNull.Value : strContentEn,
                "@ImageUrl", string.IsNullOrEmpty(strImageUrl) ? (object)DBNull.Value : strImageUrl,
                "@LinkUrl", string.IsNullOrEmpty(strLinkUrl) ? (object)DBNull.Value : strLinkUrl,
                "@NumberValue", decNumberValue.HasValue ? (object)decNumberValue.Value : DBNull.Value,
                "@NumberSuffix", string.IsNullOrEmpty(strNumberSuffix) ? (object)DBNull.Value : strNumberSuffix,
                "@SortOrder", intSortOrder,
                "@IsPublished", bolIsPublished ? 1 : 0,
                "@UserName", string.IsNullOrEmpty(strUserName) ? (object)DBNull.Value : strUserName
            );

            if (dtbData != null && dtbData.Rows.Count > 0 && dtbData.Columns.Contains("AboutPageContentID"))
            {
                object objValue = dtbData.Rows[0]["AboutPageContentID"];
                if (objValue != null && objValue != DBNull.Value)
                    return Convert.ToInt64(objValue);
            }

            return lngAboutPageContentID;
        }

        public static void Delete(long lngAboutPageContentID, string strUserName)
        {
            INFO_Information objInformation = new INFO_Information();
            objInformation.GetDataTable(
                "INFO_AboutPageContent_Delete",
                "@AboutPageContentID", lngAboutPageContentID,
                "@UserName", string.IsNullOrEmpty(strUserName) ? (object)DBNull.Value : strUserName
            );
        }

        public static void SetPublished(long lngAboutPageContentID, bool bolIsPublished, string strUserName)
        {
            INFO_Information objInformation = new INFO_Information();
            objInformation.GetDataTable(
                "INFO_AboutPageContent_SetPublished",
                "@AboutPageContentID", lngAboutPageContentID,
                "@IsPublished", bolIsPublished ? 1 : 0,
                "@UserName", string.IsNullOrEmpty(strUserName) ? (object)DBNull.Value : strUserName
