namespace InformationCMS.Controls.ContenPageAuto
{
    public partial class Edit : ControlBase
    {
        private long lngAboutPageContentID = 0;

        protected String strPermissionView = "INFO_AboutPageContent_View";
        protected String strPermissionAddEdit = "INFO_AboutPageContent_AddEdit";
        protected String strPermissionDelete = "INFO_AboutPageContent_Delete";

        protected void Page_Load(object sender, EventArgs e)
        {
            SetPermission();

            if (Globals.GetStrRequest("id", "") != "")
                lngAboutPageContentID = Convert.ToInt64(Globals.GetStrRequest("id", ""));

            if (!IsPostBack)
                LoadInfo();
        }

        private void SetPermission()
        {
            if (!User.IsPermission(strPermissionView)
                && !User.IsPermission(strPermissionAddEdit)
                && !User.IsPermission(strPermissionDelete))
            {
                Session[DCore.Globals.ERROR] = new SystemError("Bạn không được phép truy cập chức năng này", null, ReturnPage);
                Response.Redirect("~/" + MessagePage);
            }

            btnSave.Visible = User.IsPermission(strPermissionAddEdit);
            btnSaveAndBack.Visible = User.IsPermission(strPermissionAddEdit);
        }

        private void LoadInfo()
        {
            txtSortOrder.Text = "0";
            chkIsPublished.Checked = true;

            if (lngAboutPageContentID < 1)
                return;

            DataTable dtbData = AboutPageContentService.GetById(lngAboutPageContentID);
            if (dtbData == null || dtbData.Rows.Count < 1)
                return;

            DataRow drwData = dtbData.Rows[0];
            txtID.Text = Convert.ToString(drwData["AboutPageContentID"]);
            SetDropDownValue(ddlPageCode, Convert.ToString(drwData["PageCode"]));
            SetDropDownValue(ddlSectionCode, Convert.ToString(drwData["SectionCode"]));
            txtContentCode.Text = Convert.ToString(drwData["ContentCode"]);
            txtContentCode.ReadOnly = true;
            SetDropDownValue(ddlContentType, Convert.ToString(drwData["ContentType"]));
            txtTitleVi.Text = Convert.ToString(drwData["TitleVi"]);
            txtTitleEn.Text = Convert.ToString(drwData["TitleEn"]);
            txtContentVi.Text = Convert.ToString(drwData["ContentVi"]);
            txtContentEn.Text = Convert.ToString(drwData["ContentEn"]);
            txtImageUrl.Text = Convert.ToString(drwData["ImageUrl"]);
            txtLinkUrl.Text = Convert.ToString(drwData["LinkUrl"]);

            if (drwData["NumberValue"] != null && drwData["NumberValue"] != DBNull.Value)
                txtNumberValue.Text = Convert.ToString(drwData["NumberValue"]);
            else
                txtNumberValue.Text = string.Empty;

            txtNumberSuffix.Text = Convert.ToString(drwData["NumberSuffix"]);
            txtSortOrder.Text = Convert.ToString(drwData["SortOrder"]);
            chkIsPublished.Checked = Convert.ToBoolean(drwData["IsPublished"]);
        }

        private static void SetDropDownValue(DropDownList ddlControl, string strValue)
        {
            if (ddlControl == null) return;
            ListItem objItem = ddlControl.Items.FindByValue(strValue);
            if (objItem != null)
                ddlControl.SelectedValue = strValue;
        }

        private bool SaveData()
        {
            string strPageCode = ddlPageCode.SelectedValue;
            string strSectionCode = ddlSectionCode.SelectedValue;
            string strContentCode = txtContentCode.Text.Trim();
            string strContentType = ddlContentType.SelectedValue;

            if (string.IsNullOrEmpty(strPageCode)
                || string.IsNullOrEmpty(strSectionCode)
                || string.IsNullOrEmpty(strContentCode)
                || string.IsNullOrEmpty(strContentType))
            {
                return false;
            }

            int intSortOrder = 0;
            int.TryParse((txtSortOrder.Text ?? string.Empty).Trim(), out intSortOrder);

            decimal? decNumberValue = null;
            decimal decTemp = 0;
            if (decimal.TryParse((txtNumberValue.Text ?? string.Empty).Trim(), out decTemp))
                decNumberValue = decTemp;

            lngAboutPageContentID = AboutPageContentService.Save(
                lngAboutPageContentID,
                strPageCode,
                strSectionCode,
                strContentCode,
                strContentType,
                txtTitleVi.Text.Trim(),
                txtTitleEn.Text.Trim(),
                txtContentVi.Text,
                txtContentEn.Text,
                txtImageUrl.Text.Trim(),
                txtLinkUrl.Text.Trim(),
                decNumberValue,
                txtNumberSuffix.Text.Trim(),
                intSortOrder,
                chkIsPublished.Checked,
                User.UserName
            );

            return lngAboutPageContentID > 0;
        }

        protected void btnSave_Click(object sender, EventArgs e)
        {
            bool bolIsAddNew = lngAboutPageContentID <= 0;

            if (!SaveData())
            {
                MsgBox.ShowError("Vui lòng nhập đầy đủ dữ liệu bắt buộc");
                return;
            }

            MsgBox.ShowSuccess("Lưu nội dung thành công");
            if (bolIsAddNew)
                Response.Redirect("Edit.aspx?id=" + lngAboutPageContentID.ToString());
        }

        protected void btnSaveAndBack_Click(object sender, EventArgs e)
        {
            if (!SaveData())
            {
                MsgBox.ShowError("Vui lòng nhập đầy đủ dữ liệu bắt buộc");
                return;
            }

            Response.Redirect("List.aspx");
        }

        protected void btnReturn_Click(object sender, EventArgs e)
        {
            Response.Redirect("List.aspx");
        }
    }
}

